head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.clickListComiteDelibCaseSeq = "";
scwin.vScrenID = "ULDSTF60003.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_setCode = function() {
    //  기간 from~ to  셋팅	
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 일년 날짜
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
};
scwin.fn_setListComiteDelibCaseSeq = function(obj) {
    scwin.clickListComiteDelibCaseSeq = dts_List.getCellData(eval(obj), "LIST_COMITE_DELIB_CASE_SEQ");
};
scwin.fn_getListComiteDelibCaseSeq = function() {
    return scwin.clickListComiteDelibCaseSeq;
};
scwin.fn_list_sync = function() {
    var V_RSLT = " AND COMITE_INVSTG_RSLT_CD IN ( ";
    var atLeastChecked = false;
    if (chk_COMITE_RSLT1.checked) {
        V_RSLT += " '1' ";
        atLeastChecked = true;
    }
    if (chk_COMITE_RSLT2.checked) {
        if (atLeastChecked) {
            V_RSLT += ", '2' ";
        } else {
            V_RSLT += " '2' ";
        }
        atLeastChecked = true;
    }
    if (chk_COMITE_RSLT3.checked) {
        if (atLeastChecked) {
            V_RSLT += ", '3' ";
        } else {
            V_RSLT += " '3' ";
        }
        atLeastChecked = true;
    }
    if (chk_COMITE_RSLT4.checked) {
        if (atLeastChecked) {
            V_RSLT += ", '4' ";
        } else {
            V_RSLT += " '4' ";
        }
        atLeastChecked = true;
    }
    if (chk_COMITE_RSLT5.checked) {
        if (atLeastChecked) {
            V_RSLT += ", '5' ";
        } else {
            V_RSLT += " '5' ";
        }
        atLeastChecked = true;
    }
    if (chk_COMITE_RSLT6.checked) {
        if (atLeastChecked) {
            V_RSLT += ", '6' ";
        } else {
            V_RSLT += " '6' ";
        }
        atLeastChecked = true;
    }
    if (chk_COMITE_RSLT7.checked) {
        if (atLeastChecked) {
            V_RSLT += ", '7' ";
        } else {
            V_RSLT += " '7' ";
        }
        atLeastChecked = true;
    }
    if (atLeastChecked) {
        V_RSLT += " ) ";
    } else {
        V_RSLT = "";
    }
    var url = "/listingCommon.do?method=listGeneralForDynamicName&outputMessageId=COMITEDELIB_REQINF_INOUT&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&SCREN_ID=" + scwin.vScrenID + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.comite.comitedelib.select.list" + "&{P}COMITE_CASE_TP_CD=" + $c.stf.getObjectValue(cmb_COMITE_CASE_TP_CD) + "&{P}SDATE=" + $c.stf.getObjectValue(edt_SDate) + "&{P}EDATE=" + $c.stf.getObjectValue(edt_EDate) + "&{P}V_RSLT=" + V_RSLT + "&{P}COMITE_CASE_NM=" + $c.stf.getObjectValue(tbx_COMITE_CASE_NM);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_List);
};



/********************************************** 
 * 함수명   : fn_ExcelDown()
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    if (dts_List.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, "리스트", "", "3");
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};
scwin.fn_OpenDetail = async function(row) {
    if (row > 0) {
        //그리드에서 선택시
        scwin.fn_setListComiteDelibCaseSeq(row);
    } else {
        //신규버튼 선택시
        scwin.clickListComiteDelibCaseSeq = ""; //초기화

    }

    //alert('[secugrpId]'+secugrpId);
    await $c.frame.CreateDialogFrame("LIST_COMITE", "/lstmgt/ULDSTF60004.gfm", "상장위원회정보관리", 200, 0, 900, 600, "window");
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        scwin.fn_list_sync();
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.btn_Excel_onclick = function() {
    scwin.fn_ExcelDown();
};
scwin.grd_List_OnDblClick = function(row, colid) {
    if (row == 0) return;
    if (colid == 'FILE1') {
        if (dts_List.getCellData(row, "FILE1") == '') {
            $c.win.alert('첨부파일이 없습니다');
        } else {
            location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&file_id=" + dts_List.getCellData(row, "LIST_COMITE_DELIB_CASE_SEQ") + "&attach_seq=1&gubun=28";
        }
    } else if (colid == 'FILE2') {
        if (dts_List.getCellData(row, "FILE2") == '') {
            $c.win.alert('첨부파일이 없습니다');
        } else {
            location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&file_id=" + dts_List.getCellData(row, "LIST_COMITE_DELIB_CASE_SEQ") + "&attach_seq=2&gubun=28";
        }
    } else {
        scwin.fn_OpenDetail(row);
    }
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.gform_onload = function() {
    scwin.fn_setCode();
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_list_sync();
};
scwin.btn_new_onclick = function() {
    scwin.fn_OpenDetail(-999);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
